-- GRC Hub v2.0 — Seed de Frameworks
-- Gerado automaticamente — NÃO editar manualmente

-- FRAMEWORKS

-- CIS CONTROLS v8 — 153 SALVAGUARDAS

-- NIST CSF 2.0 — SUBCATEGORIAS

-- COBIT 2019 — 40 OBJETIVOS

-- ISO 42001:2023 — CONTROLES DE GOVERNANÇA DE IA

-- LGPD — ARTIGOS-CHAVE DE CONFORMIDADE

-- MAPEAMENTOS CRUZADOS ENTRE FRAMEWORKS
-- (inseridos após criação das tabelas de controles)

-- ========================================================================
-- RESOLUÇÃO DOS MAPEAMENTOS CRUZADOS
-- Converte os códigos de controle em IDs reais após inserção
-- ========================================================================
DO $$
DECLARE
  s RECORD;
  orig_id INT;
  dest_id INT;
BEGIN
  FOR s IN SELECT * FROM fw_mapeamentos_seed LOOP
    -- Detectar framework de origem pelo código
    SELECT id INTO orig_id FROM fw_controles
      WHERE codigo = s.origem_codigo
      AND framework_codigo = CASE
        WHEN s.origem_codigo LIKE 'A.%' THEN 'iso27001'
        WHEN s.origem_codigo LIKE 'CIS.%' THEN 'cis_v8'
        WHEN s.origem_codigo LIKE 'GV.%' OR s.origem_codigo LIKE 'ID.%'
          OR s.origem_codigo LIKE 'PR.%' OR s.origem_codigo LIKE 'DE.%'
          OR s.origem_codigo LIKE 'RS.%' OR s.origem_codigo LIKE 'RC.%' THEN 'nist_csf'
        ELSE s.origem_fw_guess
      END
    LIMIT 1;

    SELECT id INTO dest_id FROM fw_controles
      WHERE codigo = s.dest_codigo AND framework_codigo = s.dest_fw
    LIMIT 1;

    IF orig_id IS NOT NULL AND dest_id IS NOT NULL THEN
        VALUES(orig_id, dest_id, s.relacao, s.notas)
        ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
END $$;

-- Limpar tabela temporária de seed
DROP TABLE IF EXISTS fw_mapeamentos_seed;
